<?php require_once __DIR__.'/../includes/functions.php';need_role(['petugas']);if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/petugas/daftar_laporan.php');check_csrf();$id=(int)($_POST['id_laporan']??0);$body=trim($_POST['isi_tanggapan']??'');$s=db()->prepare('SELECT id_laporan,id_pelapor,nomor_laporan FROM reports WHERE id_laporan=? AND id_petugas=?');$s->execute([$id,me()['id_user']]);$r=$s->fetch();if(!$r||$body===''){flash('error','Laporan tidak valid atau tanggapan masih kosong.');go('/laporwarga/petugas/daftar_laporan.php');}db()->prepare('INSERT INTO responses(id_laporan,id_petugas,isi_tanggapan) VALUES(?,?,?)')->execute([$id,me()['id_user'],$body]);notify((int)$r['id_pelapor'],'Tanggapan petugas','Ada tanggapan baru pada laporan '.$r['nomor_laporan'],'/laporwarga/masyarakat/detail_laporan.php?id='.$id);log_activity('tambah_tanggapan',$r['nomor_laporan']);flash('success','Tanggapan berhasil dikirim.');go('/laporwarga/petugas/detail_laporan.php?id='.$id);